import API from './API';
import * as path from 'path';

/**
 * Commandline executable
 * @class Command
 */
export default class Command {
    constructor(binDir) {

        this.allowedCommands = [
            ["create-server", "[port] [dest] [--verbose]", "Create a sync server on current IP with specified port and designated destination directory"],
            ["start", "[url] [source] [--verbose] [--regenerateIgnoreList]", "Sync source directory to specified server url (ip:port)"]
        ];

        this.allowedOptions = [
            ["-h", "--help", "Output usage information"],
            ["-V", "--version", "Output the version number"]
        ];

        this.rootPath = path.dirname(binDir);
        this.parse();
    }

    parse() {
        let found = false;

        // process.argv for options first
        let firstArg = process.argv[2];

        // check for help
        if (firstArg === this.allowedOptions[0][0] || firstArg === this.allowedOptions[0][1]) {
            found = true;
            this.printUsage();
        }

        // check for version
        let packageInfo = require(path.join(this.rootPath, 'package.json'));

        if (firstArg === this.allowedOptions[1][0] || firstArg === this.allowedOptions[1][1]) {
            found = true;
            console.log(`\n${packageInfo.version}\n`);
        }

        // no options specified? find the command the user is trying to initiate
        if (!found) {
            let cmdLength = this.allowedCommands.length;
            for (let cmdIdx = 0; cmdIdx < cmdLength; cmdIdx++) {

                let cmdToCheck = this.allowedCommands[cmdIdx][0];
                if (firstArg === cmdToCheck) {
                    found = true;
                    let args = process.argv.slice(3, process.argv.length);
                    this.processCommand(cmdToCheck, args, (error, msg) => {
                        if (error) {
                            console.log(`\n${error}`);
                            this.printUsage();
                        }
                        else {
                            console.log(`\n${msg}\n`);
                        }
                    });

                }
            }
        }

        if (!found) {
            this.printUsage();
        }

        return found;
    }

    printUsage() {
        let rightCol = 40;

        console.log("\n  Usage: sync [options] [command]\n\n");
        console.log("  Commands:\n");

        this.allowedCommands.forEach((command) => {
            let spaceCount = rightCol - command[0].length - command[1].length;
            if (spaceCount <= 0) {
                spaceCount = 4;
            }
            let spaces = '';
            for (var i = 0; i < spaceCount; i++) {
                spaces += ' ';
            }

            console.log(`    ${command[0]} ${command[1]}${spaces}${command[2]}`);
        });

        console.log("\n  Options:\n");
        this.allowedOptions.forEach((option) => {
            let sep = ', ';

            let spaceCountOpt = rightCol - option[0].length - option[1].length - sep.length;
            if (spaceCountOpt <= 0) {
                spaceCountOpt = 4;
            }

            let spacesOpt = '';
            for (let i = 0; i < spaceCountOpt; i++) {
                spacesOpt += ' ';
            }

            console.log(`    ${option[0]}${sep}${option[1]} ${spacesOpt}${option[2]}`);
        });

        console.log('');
    }

    processCommand(command, args, callback) {
        if (command === 'create-server') {
            // [port] [dest]
            let verbose = true;
            if (args[2] === '--verbose') {
                verbose = args[3];
            }

            API.createServer(args[0], args[1], verbose, (error, msg) => {
                callback(error, msg);
            });
        }
        else if (command === 'start') {
            // [url] [source]

            let _verbose = true;
            let _regenerateIgnoreList = false;
            for (let a = 0; a < args.length; a++) {
                if (args[a] === '--verbose') {
                    _verbose = args[a+1];
                }
                if (args[a] === '--regenerateIgnoreList') {
                    _regenerateIgnoreList = args[a+1];
                }
            }

            // false == if using CLI, do not close server when done
            // url, directory, closeWhenDone, regenerateAutoIgnoreFile, verbose, cb
            var options = {
                url: args[0],
                directory:  args[1],
                closeWhenDone: false,
                regenerateIgnoreList: _regenerateIgnoreList,
                verbose: _verbose
            };
            API.uploadToServer(options, (error, msg) => {
                callback(error, msg);
            });
        }
        else {
            callback(`Undefined command: ${command}`, null);
        }
    }
}
