import Client from './Client';
import Server from './Server';
import Stopper from './Stopper';
import Command from './Command';

const stopper = new Stopper();

/**
 * @class API
 */
export default class API {

    static get Command() {
        return Command;
    }

    /**
     * @description
     * Create the jibo-sync server
     *
     * ```
     * var jiboSync = require("jibo-sync");
     * jiboSync.createServer()
     * ```
     * @method createServer
     * @static
     */
    static createServer(port, dest, verbose, cb) {
        Server.start(port, dest, verbose, (error, msg) => {
            if (error) {
                console.log(error);
                cb(error);
            }
            else {
                console.log(msg);
                cb(null);
            }
        });
    }

    /**
     * @description
     * Upload to jibo-sync server
     *
     * ```
     * var jiboSync = require("jibo-sync");
     * jiboSync.uploadToServer()
     * ```
     * @method updateToServer
     * @static
     * @param {object} options The collection of options
     * @param {string} options.url URL to connect to
     * @param {string} options.dir Directory to upload
     * @param {boolean} [options.close] Auto-close when completed
     * @pararm {boolean} [options.force] Force regenerating sync ignores
     * @param {boolean} [options.verbose] Verbose mode
     * @param {function} cb Callback when complete
     */
    static uploadToServer(options, cb) {
        // Backward compatibility to support arguments list:
        // [url, directory, closeWhenDone, verbose]
        if (typeof options !== "object") {
            options = {
                url: arguments[0],
                dir: arguments[1],
                close: arguments[2],
                force: false,
                verbose: arguments[3],
            };
            cb = arguments[4];
        }
        stopper.reset();
        Client.push(options.url, options.dir, options.force, options.verbose, (error, msg) => {
            if (options.close) {
                Client.done(options.url, (_e) => {
                    if (_e && options.verbose) {
                        console.log(_e);
                    }
                    cb(error, msg);
                });
            }
            else {
                cb(error, msg);
            }
        });
    }

    /**
     * @method closeServer
     * @static
     */
    static closeServer(url, cb) {
        Client.done(url, (error, msg) => {
            cb(error, msg);
        });
    }

    /**
     * @method closeServer
     * @stop
     */
    static stop() {
        stopper.stop();
    }
}
