import * as http from 'http';
import * as zlib from 'zlib';
import * as tarFs from 'tar-fs';
import * as Meter from 'stream-meter';
import * as request from 'request';  // only used by _tryUpload now :(
import * as chalk from 'chalk';
import Common from './Common';
import FailErrors from './FailErrors';
import Stopper from './Stopper';
import {SyncIgnore} from 'jibo-syncignore';

let stopper = new Stopper();

/**
 * Compute the absolute path of a source directory
 *
 * @param resolvePath (String) Path users passed into our system.
 *
 * Returns the absolute path version of directory
 */
function _resolvePath(_path){
    if( typeof _path !== "string"){
        // Use the current directory if no path was provided
        return ".";
    }

    // it's ok, just return it
    return _path;
}


function _getServerList(host, port) {

    return new Promise((resolve, reject) => {

        if (stopper.doStop) {
            reject(FailErrors.STOPPED);
            return;
        }
        Common.startTimer('Generating server list');

        const postOptions = {
            host: host,
            port: port,
            path: '/checksum',
            method: 'POST'
        };

        // Set up the request
        const req = http.request(postOptions, (res) => {

            if (stopper.doStop) {
                reject(FailErrors.STOPPED);
                return;
            }

            res.setEncoding('utf8');
            let strData = '';

            res.on('data', (chunk) => {
                strData += chunk;
            });

            res.on('end', (err) => {
                if (stopper.doStop) {
                    reject(FailErrors.STOPPED);
                }
                else if (err) {
                    reject('Cannot connect to ' + host + ':' + port + ' or it is already in use.');
                }
                else {
                    // always returning something; even if error there should at least be an empty checklist in the body
                    const serverList = JSON.parse(strData);
                    Common.endTimer();
                    resolve(serverList);
                }
            });
        });

        req.end();
    });
}


/**
 * Calls code in the jibo-syncignore package that searches the named directory
 * and puts all dev dependences into a file, called the .syncignore-auto file. Later,
 * this file and the custom .syncignore file will be combined, generating a
 * list of packages that should *not* be synced to jibo.
 *
 * @param  {[type]} directory  Path of package to search
 * @param  {[type]} force If true, run full search, don't used cached file
 * @param  {[type]} verbose    If true, print extra debug information
 * @return {[type]}            Array of packages
 **/
function _generateAutoIgnoreFile(directory, force/*, verbose*/) {
    return new Promise((resolve, reject) => {
        if (stopper.doStop) {
            reject(FailErrors.STOPPED);
            return;
        }
        if (force) {
            Common.log(chalk.white('Force removing .syncignore-auto file.'));
        }
        Common.startTimer('Generating ignore list');
        // Let's see if we can generate an ignore list.
        const syncignore = new SyncIgnore(directory);
        // First param should be true if we're forcing a scan, i.e. ignoring
        // the .syncignore-auto file that was generated last time
        // Second parameter should be true if we're printing debug info
        const packages = syncignore.exec(force); // debug is 2nd arg
        Common.endTimer();
        resolve(packages);
    });
}


function _getUpdateList(directory, serverList) {
    return new Promise((resolve, reject) => {
        if (stopper.doStop) {
            reject(FailErrors.STOPPED);
            return;
        }

        // get client list
        Common.generateChecksum(directory, true).then((clientList) => {

            if(stopper.doStop) {
                reject(FailErrors.STOPPED);
                return;
            }

            // determine update/delete list
            //
            let deleteList = [];
            let updateList = [];

            for (let file in clientList) {
                if (serverList.hasOwnProperty(file)) {

                    if (serverList[file] !== clientList[file]) {
                        // if the check sums differ, then add to update list
                        updateList.push(file);
                    }

                    // remove entry from server list because we already visited it
                    delete serverList[file];
                }
                else {
                    // add- doesn't exist on server
                    updateList.push(file);
                }
            }

            // whatever is left in serverList is now the delete list
            for (let deleteFile in serverList) {
                deleteList.push(deleteFile);
            }

            resolve({updateList, deleteList});

        }).catch((error) => {
            reject('Error retrieving update list:  ' + error);
        });
    });
}


function _upload(host, port, directory, updateList, deleteList) {
    return new Promise((resolve, reject) => {
        if(stopper.doStop) {
            reject(FailErrors.STOPPED);
            return;
        }
        if (deleteList.length === 0 && updateList.length === 0) {
            Common.log(chalk.gray("Everything is already up to date."));
            resolve({size: 0, compSize: 0});
            return;
        }

        // try to delete first
        _tryDelete(host, port, deleteList, (err) => {
            if(stopper.doStop) {
                reject(FailErrors.STOPPED);
                return;
            }
            if (err) {
                Common.log(chalk.red('Delete failed: ' + err));
                // don't return...keep going even if delete failed
            }

            // try to upload now
            _tryUpload(host, port, updateList, directory, (err, size, compSize) => {
                if(stopper.doStop) {
                    reject(FailErrors.STOPPED);
                }
                else if(err) {
                    reject(err);
                }
                else {
                    resolve({size, compSize});
                }
            });
        });
    });

}


function _tryDelete(_host, _port, _deleteList, cb) {

    if (_deleteList.length > 0) {
        Common.startTimer('Deleting ' + _deleteList.length + ' files');

        const body = JSON.stringify({
            deleteList: _deleteList
        });

        const postOptions = {
            host: _host,
            port: _port,
            path: '/delete',
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': body.length
            }
        };

        // Set up the request
        const req = http.request(postOptions, (res) => {
            let str = '';
            res.on('data', (chunk) => {
                str += chunk;
            });

            res.on('end', () => {
                Common.endTimer();
                if (res.status === 'ERROR') {
                    cb(str);
                }
                else {
                    cb(null);
                }
            });
        });

        req.on('error', (e) => {
            cb(e);
        });

        req.write(body);
        req.end();
    }
    else {
        cb(null);
    }
}


function _tryUpload(_host, _port, updateList, directory, cb) {
    // Then send the update list
    if (updateList.length > 0) {

        Common.startTimer('Updating ' + updateList.length + ' files');

        const upUrl = 'http://' + _host + ':' + _port + '/upload';
        const req = request.post(upUrl);

        const sizeMeter = new Meter();
        const compressedMeter = new Meter();

        const targzStream = tarFs.pack(directory, {
            entries: updateList,   // only send over the files that need it
            dereference: true      // keep file stat permissions
        });

        const stream = targzStream
            .pipe(sizeMeter)
            .pipe(zlib.createGzip({level: 9}))
            .pipe(compressedMeter)
            .pipe(req);

        stopper.once('stop', () => {
            stream.abort();
            cb(FailErrors.STOPPED);
        });

        stream.on('end', (err) => {
            Common.endTimer();
            cb(err, sizeMeter.bytes, compressedMeter.bytes);
        });

        stream.on('error', (err) => {
            cb(err, null, null);
        });
    }
    else {
        cb(null, 0, 0);
    }
}

class Client {

    static push(_url, _directory, force, verbose, cb) {

        // update verbose flag
        Common.setVerbose(verbose);

        // extract host IP and port from url
        let urlData = Common.getHostPort(_url);
        if (!urlData) {
            cb('Error parsing url into host:port');
            return;
        }

        let host = urlData.host;
        let port = urlData.port;
        let directory = _resolvePath(_directory);
        let start = Date.now();

        // 1. get server list
        // 2. generate autoignore file
        // 2. get update list
        // 3. upload
        Common.log(chalk.white.bold.underline('Working directory:') + ' ' + chalk.white(directory) + '\n');
        let _serverList = null;
        _getServerList(host, port).then((serverList) => {
            _serverList = serverList; // save this for later
            return _generateAutoIgnoreFile(directory, force, verbose);
        }).then((/*packageList*/) => {
            return _getUpdateList(directory, _serverList);
        }).then((lists) => {
            return _upload(host, port, directory, lists.updateList, lists.deleteList);
        }).then(() => {
            cb(null, 'Completed in ' + (Date.now() - start)/1000 + ' seconds');
        }).catch((e) => {
            cb(e);
        });
    }

    static done(_url, cb) {
        let urlData = Common.getHostPort(_url);
        if (!urlData) {
            cb('Error parsing url into host:port', null);
            return;
        }

        let postOptions = {
            host: urlData.host,
            port: urlData.port,
            path: '/close',
            method: 'POST'
        };

        // Set up the request
        let req = http.request(postOptions, (res) => {
            let chunk = "";
            res.on('data', function (data) {
                chunk += (data);
            });

            res.on('end', () => {
                let data;
                try {
                    data = JSON.parse(chunk);
                }
                catch(e) {
                    res.writeHead(200, {'Content-Type': 'text/html'});
                    res.write(JSON.stringify({
                        Status: 'ERROR',
                        Message: 'Invalid request to close sync server. Request body is not valid JSON'
                    }));
                    res.end();
                    return;
                }

                if (data.Status === 'ERROR') {
                    cb(data.Message, null);
                }
                else {
                    cb(null, data.Message);
                }
            });
        });

        req.end();
    }
}

Client.FAIL_ERRORS = FailErrors;

export default Client;
