import * as async from 'async';
import * as crypto from 'crypto';
import * as fs from 'fs';
import * as path from 'path';
import * as util from 'util';
import * as chalk from 'chalk';
import Stopper from './Stopper';
import FailErrors from './FailErrors';
import {SyncIgnore} from 'jibo-syncignore';

//
// Global flag for which method to generate update list (checksum vs timestamps)
//
let useTimestamp = true;

let stopper = new Stopper();

function log(/*msg*/) {
    Common.log.apply(Common, arguments);
}

function _findFilesRecursive(baseDir, currentDir, ignoreGlobs, ignorePaths, callback) {
    if (stopper.doStop) {
        callback(FailErrors.STOPPED);
        return;
    }

    // 1. get all the files/directories in the current dir
    fs.readdir(currentDir, (error, curFiles) => {
        if (error) {
            callback(error, null);
            return;
        }

        // 2. filter out our ignored files/directories
        let files = [];
        let nextDirs;

        curFiles = curFiles.filter( (name) => {
            const rootRelativePath = '/' + path.relative(
                baseDir, path.join(currentDir, name)
            ).replace(/\\/g, '/');

            // See if the current path matchs any existing folder
            // this is faster than looping through all globs
            //  or using regular expressions
            let dir = rootRelativePath;
            while (dir !== '/') {
                if (ignorePaths.indexOf(dir) > -1) {
                    // log('--- ignore (path)', rootRelativePath);
                    return false;
                }
                dir = path.dirname(dir);
            }

            // Loop thru the glob, which have been converted to regular
            // expressions, if the file or directory should be ignored
            for (let i = 0, len = ignoreGlobs.length; i < len; ++i) {
                if (ignoreGlobs[i].test(rootRelativePath)) {
                    // log('--- ignore (glob)', rootRelativePath);
                    return false
                }
            }
            return true;
        });

        // 3. get our next directories to recurse through
        nextDirs = curFiles.filter( (name) => {
            if (!currentDir) {
                return false;
            }

            let filepath = path.join(currentDir, name);

            try {
                let stat = fs.statSync(filepath);
                return (stat && stat.isDirectory());
            }
            catch(e) {
                log(chalk.red("Error getting file info on " + filepath + "; skipping.."));
                return false;
            }
        });

        // 4. filter current files to only be files now (not directories)
        curFiles = curFiles.filter( (name) => {
            if (!currentDir) {
                return false;
            }

            let filepath = path.join(currentDir, name);

            try {
                let stat = fs.statSync(filepath);
                return (stat && stat.isFile());
            }
            catch(e) {
                log(chalk.red("Error getting file info on " + filepath + "; skipping.."));
                return false;
            }
        });

        // 5. make sure they are all correct relative paths
        curFiles = curFiles.map( (name) => {
            return path.join(currentDir, name);
        });

        // 6. tack them on to our master list
        files = files.concat(curFiles);

        // 7. recurse!
        let tasks = [];
        nextDirs.forEach( (dir) => {
            tasks.push( (cb) => {
                // loop recursively through the allowed directories now
                let nextDir = path.join(currentDir, dir);
                _findFilesRecursive(baseDir, nextDir, ignoreGlobs, ignorePaths, (error, newFiles) => {
                    files = files.concat(newFiles);
                    cb();
                });
            });
        });

        async.parallelLimit(tasks, 5, (error) => {
            if(stopper.doStop) {
                callback(FailErrors.STOPPED);
            }
            else if (error) {
                console.error('Error executing recursive file find: ' + error);
                callback(error, null);
            }
            else {
                callback(null, files);
            }
        });
    });
}


//
// Asynchronously loading file and getting checksum hash value
//
function _getChecksum(filename, cb) {
    if (!filename) {
        cb(null);
        return;
    }

    if (useTimestamp) {
        fs.stat(path.normalize(filename), (error, stats) => {
            if (stats) {
                let time = stats.mtime;
                if(util.isDate(time)) {
                    // convert to 123.456 UNIX timestamp
                    time = Math.trunc(time.getTime() / 1000);
                }
                cb(time);
                return;
            }

           log(chalk.red('Error getting checksum for ' + filename + ': ' + error));
           cb(null);
        });
    }
    else {
        fs.readFile(path.normalize(filename), (error, data) => {
            if (data) {
                let cksum = crypto.createHash('md5');
                cksum.update(data);
                cb(cksum.digest('hex'));
                return;
            }

            log(chalk.red('Error getting checksum for ' + filename + ': ' + error));
            cb(null);
        });
    }
}

Math.trunc = Math.trunc || function(x) {
        return x < 0 ? Math.ceil(x) : Math.floor(x);
};

function ignore(directory, file) {
    const ignorePath = path.resolve(directory, file);
    try {
        return fs.readFileSync(ignorePath, 'utf8')
            .split(/[\n\r]/g)
            .filter((item) => {
                return !!item;
            });
    }
    catch(e) {
        return [];
    }
}

class Common {

    static generateChecksum(directory, useIgnore) {
        return new Promise((resolve, reject) => {
            if(!directory) {
                reject(FailErrors.NO_DIRECTORY);
                return;
            }

            // All the packages that are going to be ignored because they're in the .syncignore-auto file.
            // (This is automatically generated by jibo-syncignore)
            let autoIgnorePatterns = (useIgnore ? ignore(directory, SyncIgnore.FILENAME) : []);

            // All the packages that are going to be ignored because they're in the .syncignore file.
            let ignorePatterns = (useIgnore ? ignore(directory, SyncIgnore.FILENAME_LOCAL) : []);
            ignorePatterns = autoIgnorePatterns.concat(ignorePatterns);

            // convert absolute paths to relative (only for unix/osX?)
            let baseDir = directory.replace(/\/$/, '');

            // check if source exists first...
            fs.stat(baseDir, (error, stats) => {
                if (error || (stats && !stats.isDirectory())) {
                    let errorMsg = 'Directory ' + baseDir + ' does not exist.';
                    reject(errorMsg); // empty list
                    return;
                }

                // get an array of the files within the directory
                Common.startTimer('Retrieving file list');

                // Filter a list of paths that are globs only
                const ignoreGlobs = ignorePatterns.filter((item) => {
                    if (item.indexOf('!') === 0) {
                        console.warn('WARNING: Includes are not longer supported in syncignore (%s)', item);
                        return false;
                    }
                    // Select anything with a glob
                    return item.indexOf('*') > -1;
                }).map((item) => {
                    // Convert glob path to regular expression
                    // doing this once and caching is faster than using
                    // minimatch, the previous implementation
                    return new RegExp('\\b' + item
                        .replace(/\//g, '\/')
                        .replace(/\./g, '\\.')
                        .replace(/([\/])?\*+([\/])?/g, '$1?.*$2')
                        .replace(/^\?/, '') // cannot start with "?"
                        + '\\b' // add word boundries to be less greedy
                    );
                });

                // Filter a list of paths that are absolute paths only
                const ignorePaths = ignorePatterns.filter((item) => {
                    return item.indexOf('*') === -1 && item[0] !== '!';
                }).map((item) => {
                    if (item[0] !== '/') {
                        item = '/' + item;
                    }
                    return item;
                });

                _findFilesRecursive(baseDir, baseDir, ignoreGlobs, ignorePaths, (error, _list) => {
                    if (error) {
                        reject(error);
                        return;
                    }

                    Common.endTimer();

                    let list = _list;
                    list = list.map( (filepath) => {
                        // remove baseDir once we're done
                        return path.relative(baseDir, filepath);
                    });

                    // now loop through the list to get our checksums
                    let tasks = [];
                    let checksumList = {};
                    list.forEach( (file) => {
                        tasks.push( (_cb) => {
                            if(stopper.doStop) {
                                _cb(FailErrors.STOPPED);
                                return;
                            }
                            // initially normalize for file read/get checksum
                            file = path.normalize(file);
                            let relativeFile = path.join(baseDir, file);
                            _getChecksum(relativeFile, (hash) => {
                                if (hash) {
                                    // then actually store it in a consistent way: representing directories in unix-style
                                    file = file.replace(/\\/g, "/");
                                    checksumList[file] = hash;
                                }
                                _cb();
                            });
                        });
                    });

                    Common.startTimer("Generating checksum list");
                    async.parallelLimit(tasks, 5, (error) => {
                        if (error) {
                            log(chalk.red('Error executing checksums: ' + error));
                            reject(error);
                        }
                        else {
                            Common.endTimer();
                            resolve(checksumList);
                        }
                    });
                });
            });
        });
    }

    static getHostPort(_url) {
        // extract host and port from url; return as object if found; otherwise undefined is returned

        let strArray = _url.split(':');
        if (strArray.length !== 2) {
            log(chalk.red('Url is not specified as [IP:port]: ' + _url));
            return undefined;
        }

        let host = strArray[0];

        // check we have a numerical port defined
        let port = Number(strArray[1]); // decimal conversion
        if (isNaN(port)) {
            log(chalk.red('Invalid port defined ' + port));
            return undefined;
        }

        return {
            "host": host,
            "port": port
        };
    }

    static setVerbose(enable) {
        Common.verboseLog = enable;
    }

    static log(/*str*/) {
        if (Common.verboseLog) {
            console.log.apply(console, arguments);
        }
    }

    static startTimer(str) {
        if (Common.verboseLog) {
            process.stdout.write(chalk.white(str) + ' ... ');
            Common._start = Date.now();
        }
    }

    static endTimer() {
        if (Common.verboseLog) {
            console.log(
                chalk.white('done.'),
                chalk.gray((Date.now() - Common._start) / 1000),
                chalk.gray('secs')                
            );
            Common._start = null;
        }
    }

    static error(str) {
        if (Common.verboseLog) {
            console.error(str);
        }
    }
}

Common._start = null;
Common.verboseLog = false;

export default Common;
