import * as async from 'async';
import * as fs from 'fs-extra';
import * as http from 'http';
//import net from 'net';
import * as Meter from 'stream-meter';
import * as path from 'path';
import * as tarFs from 'tar-fs';
import * as zlib from 'zlib';
import Common from './Common';

// global server variable for this process
let server = undefined;
let port = undefined; // default
let uploadDir = '.'; // default

const URLUPLOAD = '/upload';
const URLDELETE = '/delete';
const URLCHECKSUM = '/checksum';
const URLCLOSE = '/close';
const URLPING = '/ping';

const exec = require('child_process').exec;

// function which handles requests and send response
function _handleRequest(request, response) {
    if (request.method !== 'POST') {
        // only handling POST requests
        return;
    }

    switch (request.url) {
        case URLUPLOAD: {
            _upload(request, response);
            break;
        }

        case URLDELETE: {
            _delete(request, response);
            break;
        }

        case URLCHECKSUM: {
            _getChecksum(request, response);
            break;
        }

        case URLCLOSE: {
            _closeServer(request, response);
            break;
        }

        case URLPING: {
            _pingServer(request, response);
            break;
        }

        default: {
            response.writeHead(200, {'Content-Type': 'text/html'});
            response.write(JSON.stringify({
                Status: 'ERROR',
                Message: 'Undefined url: ' + request.url
            }));
            response.end();
            break;
        }
    }
}


function stop(cb) {
    if (server) {
        server.close();
        server = undefined;
        cb(null, 'Server closed on port ' + port);
    }
    else {
        cb('No server to close', null);
    }
}


function _getChecksum(req, res) {
    if (req.method === 'POST') {
        // false === do not use ignore list to generate checksum
        Common.generateChecksum(uploadDir, false).then((ckList) => {
            res.writeHead(200, {'Content-Type': 'text/html'});
            res.write(JSON.stringify(ckList));
            res.end();
        }).catch((error) => {
            res.writeHead(200, {'Content-Type': 'text/html'});
            res.write(JSON.stringify({
                Status: 'ERROR',
                Message: error
            }));
            res.end();
        });
    }
}

function _setPermissions(callback) {
    exec('chown -R root:root /opt/jibo/Jibo/Skills && chmod -R 755 /opt/jibo/Jibo/Skills', (error/*, stdout, stderr*/) => {
        if (error) {
            Common.log('Error setting permissions', error);
            return callback(error);
        }
        console.log(`Permissions set`);
        callback();
    });
}

function _upload(req, res) {
    Common.log('Receiving upload...');
    let startTime = Date.now();
    if (req.method === 'POST') {
        _untar(req, uploadDir, (err, bytes, compressedBytes) => {
            _setPermissions((err) => {
                if(!err) {
                    Common.log('\ttook ' + (Date.now() - startTime)/1000 + ' secs');
                    Common.log('\t' + bytes + ' bytes uploaded (' + compressedBytes + ' compressed)');
                }


                res.writeHead(200, "OK", {'Content-Type': 'text/html'});
                res.end();
            })
        });
    }
}


function _untar(stream, directory, callback) {
    fs.ensureDirSync(directory);

    let sizeMeter = new Meter();
    let compressedMeter = new Meter();
    //let dots = new Dots();
    let extractOpts = {dmode: 0o755, fmode: 0o755};  // all dirs and files should be readable

    stream.pipe(compressedMeter)
        .pipe(zlib.createGunzip())
        .pipe(sizeMeter)
        .pipe(tarFs.extract(directory, extractOpts))
        .on('finish', (err) => {
            if (err) {
                Common.log('Problem extracting tar stream', err);
                callback(err);
            } else {

                callback(null, sizeMeter.bytes, compressedMeter.bytes);
            }
        });

    stream.on('error', (err) => {
        if (err) {
            Common.log('problem with POST stream', err);
        }
        callback(err);
    });
}


function _delete(req, res) {
    Common.log('Receiving delete request...');

    let startTime = Date.now();

    if (req.method === 'POST') {
        let body = "";
        req.on('data', (chunk) => {
            body += chunk;
        });

        req.on('end', () => {
            let data = undefined;
            try {
                data = JSON.parse(body);
            }
            catch(error) {
                res.writeHead(200, {'Content-Type': 'text/html'});
                res.write(JSON.stringify({
                    Status: 'ERROR',
                    Message: 'Invalid delete request. Request body is not valid JSON'
                }));
                res.end();
                return;
            }

            let list = data.deleteList;
            if (list !== undefined) {

                let tasks = [];
                list.forEach( (file) => {

                    tasks.push( (cb) => {
                        // use absolute path for deleting
                        let filePath = path.resolve(uploadDir, file);
                        //console.log('Deleting ' + filePath);

                        fs.remove(filePath, cb);
                    });
                });

                async.parallelLimit(tasks, 5, (error) => {
                    if (error) {
                        Common.log('Error executing deletes: ' + error);
                        res.writeHead(200, "OK", {'Content-Type': 'text/html'});
                        res.write(JSON.stringify({
                            Status: 'ERROR',
                            Message: error
                        }));

                        res.end();
                    }
                    else {
                        res.writeHead(200, "OK", {'Content-Type': 'text/html'});
                        res.end();
                    }

                    Common.log('\ttook ' + (Date.now() - startTime)/1000 + ' secs');
                });
            }
        });
    }
}


function _closeServer(req, res) {
    stop((error, msg) => {
        if (error) {
            Common.log(error);

            res.writeHead(200, {'Content-Type': 'text/html'});
            res.write(JSON.stringify({
                Status: 'ERROR',
                Message: error
            }));
            res.end();
        }
        else {
            Common.log(msg);

            res.writeHead(200, "OK", {'Content-Type': 'text/html'});
            res.write(JSON.stringify({
                Status: 'OK',
                Message: msg
            }));
            res.end();
        }
    });
}


function _pingServer(req, res) {
    if (req.method === 'POST') {
        res.writeHead(200, "OK", {'Content-Type': 'text/html'});
        res.end();
    }
}

export default class Server {
    static start(_port, _dest, verbose, cb) {
        Common.setVerbose(verbose);

        port = Number(_port); // decimal conversion
        if (isNaN(port)) {
            cb('\nInvalid port defined: ' + port + ' Aborting.', null);
            return;
        }

        // check if server is already running
        if (server) {
            // server still around? make sure the tcp socket is still open
            //let socket = net.connect({port: port}, () => {
            //    // connected! hmmm...
            //    cb(null, '\nSync server starting and listening on port ' + port + '. Press CTRL+C or call stop() to exit.');
            //    return;
            //});
            //socket.on('error', (err) => {
            //    console.log("error attempting to connect: " + err);

            if (_dest) {
                uploadDir = _dest;
            }

            cb(null, '\nSync server already listening on port ' + port);
                //return;
    //        });
        }
        else {

            if (_dest) {
                uploadDir = _dest;
            }

            server = http.createServer(_handleRequest);
            try {
                server.listen(port, "0.0.0.0", (error) => {
                    if (error) {
                        server.close();
                        server = undefined;
                        cb(error, null);
                    }
                    else {
                        cb(null, '\nSync server listening on port ' + port + '. Press CTRL+C or call stop() to exit.\n');
                    }
                });
                server.timeout = 0; // setting socket time out to 0 to disable (default was 2 mins)
            }
            catch (error) {
                server.close();
                server = undefined;
                cb(error, null);
            }
        }
    }
}
